import java.io.*;
import java.util.*;

public class Main {
    static final PrintWriter outStream = new PrintWriter(System.out);
    static final FastReader inStream = new FastReader();

    public static void main(String[] args) {
        int testCases = 1;
        for (int t = 0; t < testCases; t++) {
            runSolution();
        }
        outStream.flush();
    }

    public static void runSolution() {
        int n = getNextInt();
        double p = getNextDouble();

        int leftBound = 0;
        int rightBound = n - 1;
        while (leftBound < rightBound) {
            int mid = (leftBound + rightBound) / 2;
            double val = computeProbability(mid, n);
            if (val >= p) {
                rightBound = mid;
            } else {
                leftBound = mid + 1;
            }
        }
        outStream.println(leftBound);
    }

    private static double computeProbability(int m, int n) {
        long totalComb = choose(n, 3);
        double res = 0.0;
        res += (double) choose(m, 3);
        res += (double) (choose(m, 2) * choose(n - m, 1));
        res += 0.5 * (choose(m, 1) * choose(n - m, 2));
        return res / totalComb;
    }

    private static long choose(int n, int c) {
        if (c > n) return 0;
        if (c == n) return 1;
        long res = 1;
        for (int i = 0; i < c; i++) {
            res *= (n - i);
        }
        for (int i = 1; i <= c; i++) {
            res /= i;
        }
        return res;
    }

    static int getNextInt() {
        return inStream.nextInt();
    }

    static double getNextDouble() {
        return inStream.nextDouble();
    }
}
